contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(c.blacklist(address(this)) == false);
        require(c.distributionFinished() == false);

        address caller = address(this);
        uint256 totalRemainingBefore = c.totalRemaining(); if (__ESBMC_reverted()) return;
        uint256 totalDistributedBefore = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 callerBalanceBefore = c.balanceOf(caller); if (__ESBMC_reverted()) return;

        c.getTokens{value: amount}(); if (__ESBMC_reverted()) return;

        uint256 totalRemainingAfter = c.totalRemaining(); if (__ESBMC_reverted()) return;
        uint256 totalDistributedAfter = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 callerBalanceAfter = c.balanceOf(caller); if (__ESBMC_reverted()) return;
        uint256 tokensGiven = callerBalanceAfter - callerBalanceBefore;

        assert((tokensGiven > 0 && c.blacklist(caller)) || (tokensGiven == 0 && totalRemainingAfter == totalRemainingBefore && totalDistributedAfter == totalDistributedBefore));
    }

    receive() external payable {}
}

